-- =============================================================
-- 00011_seed_dca_m2.sql
-- DCA Docker Certified Associate — 追加50問 (q32–q81)
-- =============================================================

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb, v.correct_index, v.correct_indices::jsonb, v.question_type, v.explanation_data::jsonb, 0
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  -- ============================================================
  -- Image Creation, Management, and Registry (q32–q46)
  -- ============================================================

  ('dca-q32', 'Image Creation, Management, and Registry',
   'Dockerfile の COPY と ADD の違いとして正しいものはどれか。',
   NULL,
   '["ADD は URL からのダウンロードと tar 展開が可能、COPY はローカルファイルのみ","COPY は URL からのダウンロードが可能、ADD はローカルのみ","ADD と COPY は完全に同一の機能を持つ","COPY は圧縮ファイルを自動展開するが ADD は展開しない"]',
   0, '[0]', 'single',
   '{"asked":"ADD と COPY の機能差を理解し、どちらを使うべきか判断できるか。","terms":[["COPY","ホストのファイル／ディレクトリをイメージにコピーする。シンプルで予測可能な動作。Dockerfile のベストプラクティスでは特別な理由がなければ COPY を推奨。"],["ADD","COPY の機能に加え、①HTTP/HTTPS URL から直接ダウンロード、②.tar .tar.gz などの圧縮ファイルを自動展開する追加機能を持つ。"]],"think":"COPY は普通の引越し業者（荷物をそのまま運ぶ）。ADD はスーパー引越し業者（ネット通販から荷物を取り寄せたり、梱包を解いて並べてくれる）。便利だが挙動が複雑になる。","vs":"ベストプラクティスは『COPY を基本にし、tar 展開や URL 取得が本当に必要なときだけ ADD を使う』。ADD の自動展開は意図しないファイル配置を招くことがある。URL ダウンロードには RUN curl の方が透明性が高いとされる。","opt":["正解。ADD には URL 取得と tar 自動展開の追加機能がある。","逆。COPY がローカル専用で URL は不可。","2つは機能が異なる。","COPY は自動展開しない。ADD が展開する。"]}'),

  ('dca-q33', 'Image Creation, Management, and Registry',
   'Dockerfile の ARG と ENV の違いとして正しいものはどれか。',
   NULL,
   '["ARG はビルド時のみ有効、ENV はビルド時と実行時の両方で有効","ENV はビルド時のみ有効、ARG は実行時のみ有効","ARG と ENV は機能が同一で使い分けは不要","ARG で定義した値は docker inspect で確認できない"]',
   0, '[0]', 'single',
   '{"asked":"ビルド変数（ARG）と環境変数（ENV）のスコープの違いを理解しているか。","terms":[["ARG","docker build --build-arg で渡すビルド時専用の変数。RUN 等でビルド中だけ参照できる。コンテナ実行時には引き継がれない。"],["ENV","ビルド時に設定し、コンテナ実行時の環境変数としても引き継がれる。docker inspect や printenv で確認可能。"]],"think":"ARG は工事中だけ使う仮設資材（ビルド後は片付けられる）。ENV は完成した建物に備え付けられた設備（住んでいる間ずっと使える）。","vs":"ARG の値は docker history に平文で残るため、シークレット（パスワード等）を ARG に入れてはいけない。ENV は docker inspect でも見えるので、機密値には Docker secrets を使う。","opt":["正解。ARG はビルド時だけ、ENV は両フェーズで有効。","逆の説明。","2つはスコープが異なる。","ARG の値は docker history で確認できてしまう（漏洩リスク）。"]}'),

  ('dca-q34', 'Image Creation, Management, and Registry',
   'RUN の exec 形式（JSON 配列形式）と shell 形式の違いとして正しいものはどれか。',
   'RUN ["apt-get", "install", "-y", "curl"]  -- exec 形式\nRUN apt-get install -y curl                -- shell 形式',
   '["exec 形式はシェルを介さず直接実行するため、シェル変数展開が効かない","shell 形式はシェルを介さないため高速","exec 形式は /bin/sh を必ず呼び出す","shell 形式では $PATH が参照できない"]',
   0, '[0]', 'single',
   '{"asked":"exec 形式と shell 形式の実行メカニズムの違いと使い分けを理解しているか。","terms":[["exec 形式（JSON 配列）","シェルを起動せずカーネルが直接プロセスを exec する。シェル変数展開（$VAR）・パイプ・リダイレクトは使えない。CMD/ENTRYPOINT では推奨。"],["shell 形式","/bin/sh -c コマンド文字列 として実行される。シェルの機能（変数展開・パイプ等）が使える。RUN では一般的に使われる。"]],"think":"exec 形式は『上司に直接電話する』感覚（仲介なし）。shell 形式は『秘書（シェル）を通じて指示する』感覚。秘書を通すと言葉の解釈・変換（変数展開・パイプ）をしてくれる。","vs":"ENTRYPOINT や CMD を exec 形式で書くのが推奨される理由は、シグナル（SIGTERM）がコンテナのメインプロセス（PID 1）に直接届くため。shell 形式だとシェルが PID 1 になりシグナルが子プロセスに届かない。","opt":["正解。exec 形式はシェルを介さないのでシェル変数展開不可。","shell 形式の方がシェルを起動する分オーバーヘッドがある。","exec 形式は /bin/sh を呼ばない。","shell 形式でも $PATH は参照できる（シェル経由なので）。"]}'),

  ('dca-q35', 'Image Creation, Management, and Registry',
   '.dockerignore ファイルの主な役割はどれか。',
   NULL,
   '["docker build のビルドコンテキストから特定ファイルを除外し、イメージサイズ削減とシークレット漏洩防止に使う","Dockerfile 自体のコメント行を無視するための設定ファイル","docker run で特定のボリュームをマウントしないよう指定するファイル","コンテナ実行時に特定の環境変数を除外するファイル"]',
   0, '[0]', 'single',
   '{"asked":".dockerignore の目的とセキュリティ上の意義を理解しているか。","terms":[[".dockerignore","docker build 時にデーモンへ送るビルドコンテキストから除外するファイル・ディレクトリのパターンを定義する。.gitignore と同じ書式。"],["ビルドコンテキスト","docker build . の . で指定したディレクトリ全体がデーモンに転送される。大きいほどビルドが遅くなり、機密ファイルが混入するリスクがある。"]],"think":"引越し業者への荷物リストから『段ボールの空箱』や『日記帳（機密）』を除外するリスト。.dockerignore に .env や node_modules を書けば、それらはビルドコンテキストに含まれない。","vs":".gitignore と混同しやすいが、.gitignore は git 管理の除外で .dockerignore はビルドコンテキストの除外。両方に書く必要がある。例: .env は両方に書くべき。","opt":["正解。ビルドコンテキストからの除外でサイズ削減＋機密保護。","Dockerfile のコメントは # で書く。専用ファイルは不要。","マウント除外の設定ではない。","実行時の環境変数除外ではない。"]}'),

  ('dca-q36', 'Image Creation, Management, and Registry',
   'docker commit でコンテナからイメージを作成することが推奨されない主な理由はどれか。',
   NULL,
   '["どの操作でイメージが作られたか再現できず、再ビルドができないため","docker commit で作ったイメージは Docker Hub に push できないため","docker commit は root 権限がないと使えないため","docker commit はイメージを圧縮しないためサイズが大きくなるため"]',
   0, '[0]', 'single',
   '{"asked":"docker commit の問題点とDockerfile による宣言的ビルドの利点を理解しているか。","terms":[["docker commit","実行中コンテナの現在の状態をイメージとしてスナップショットする。変更履歴（どのコマンドを実行したか）は記録されない。"],["Dockerfile","イメージの構築手順を宣言的に記述したファイル。バージョン管理でき、誰でも再ビルドできる。"]],"think":"レシピなしで適当に作った料理（commit）と、レシピ（Dockerfile）に従って作った料理の違い。レシピなしだと同じものを再現できない。チームで共有も難しい。","vs":"docker commit は緊急のデバッグや一時的なスナップショットには有用だが、本番イメージの構築には使うべきでない。CI/CD では必ず Dockerfile を使う。","opt":["正解。再現性がなく IaC（Infrastructure as Code）の原則に反する。","push 自体は可能。","root 権限の問題ではない。","サイズは問題の主因ではない。"]}'),

  ('dca-q37', 'Image Creation, Management, and Registry',
   'Dockerfile の HEALTHCHECK 命令の役割はどれか。',
   'HEALTHCHECK --interval=30s --timeout=10s --retries=3 \\\n  CMD curl -f http://localhost/health || exit 1',
   '["コンテナが正常に動作しているか定期的にチェックし、結果を docker ps の STATUS に反映する","ホストマシンのヘルスを監視してコンテナを自動再起動する","Swarm サービスのヘルスチェックとして自動適用される","コンテナ起動時に1回だけ実行されるウォームアップコマンド"]',
   0, '[0]', 'single',
   '{"asked":"HEALTHCHECK 命令の動作と docker ps への反映を理解しているか。","terms":[["HEALTHCHECK","指定したコマンドを一定間隔で実行し、戻り値（0=healthy, 1=unhealthy）をコンテナの健康状態として記録する。"],["STATUS（docker ps）","healthy / unhealthy / starting の状態が表示される。Swarm では unhealthy なタスクを自動で再スケジュールする。"]],"think":"患者のベッドに定期的に来る看護師（HEALTHCHECK）が体温・脈を計って記録する。看護師が来るのは入院中ずっと（定期実行）。カルテに状態（healthy/unhealthy）が記録される。","vs":"HEALTHCHECK はホストの監視ではなくコンテナ内部のアプリの確認。1回限りの実行ではなく定期実行。Swarm では HEALTHCHECK の結果に基づいてタスクを再スケジュールするが、単体 docker run では自動再起動しない（そちらは --restart ポリシー）。","opt":["正解。定期チェックして STATUS に反映する。","ホストではなくコンテナ内アプリのチェック。","Swarm でも適用されるが Swarm 専用の命令ではない。","1回限りではなく定期実行。"]}'),

  ('dca-q38', 'Image Creation, Management, and Registry',
   'docker save と docker export の違いとして正しいものはどれか。',
   NULL,
   '["save はイメージ全体（レイヤー・タグ含む）を tar で保存、export はコンテナのファイルシステムを履歴なしで tar に書き出す","export はイメージのレイヤーを含むが save はメタデータのみ保存する","save も export も同一のフォーマットで出力される","export は Docker Hub へのエクスポートコマンド"]',
   0, '[0]', 'single',
   '{"asked":"docker save（イメージ保存）と docker export（コンテナ FS 書き出し）の目的と出力の違いを理解しているか。","terms":[["docker save","イメージを tar アーカイブに保存。レイヤー構造・タグ・メタデータを保持。docker load で復元可能。オフライン転送に使う。"],["docker export","実行中（または停止中）のコンテナのファイルシステムを tar に書き出す。レイヤー履歴なし・フラット構造。docker import でイメージ化できる。"]],"think":"save は『本棚ごと梱包』（レイヤーという棚板まで保存）。export は『本棚から本だけ取り出して段ボールに詰める』（ファイルだけ、棚板の構造は消える）。","vs":"load は save の対、import は export の対。混同注意。save/load のペアはイメージの完全な移送、export/import のペアはファイルシステムの移植（歴史は消える）。","opt":["正解。save はレイヤー付きイメージ保存、export はコンテナ FS の平坦な書き出し。","逆の説明。","フォーマットは異なる（save はレイヤー構造あり）。","Hub へのエクスポートは docker push。"]}'),

  ('dca-q39', 'Image Creation, Management, and Registry',
   'イメージの latest タグを使うことが本番環境で問題になる主な理由はどれか。',
   NULL,
   '["latest は pull のたびに異なるイメージを取得する可能性があり、再現性がなくなる","latest タグは Docker Hub でのみ有効でプライベートレジストリでは使えない","latest タグは自動的に最新の安定バージョンを指すと保証されている","latest は圧縮率が低く pull が遅くなる"]',
   0, '[0]', 'single',
   '{"asked":"latest タグの可変性によるデプロイの再現性問題を理解しているか。","terms":[["latest タグ","Docker が自動付与する特別なタグではなく、イメージ作成者が手動で付けるタグ。push のたびに別のイメージを指す可能性がある（可変）。"],["イミュータブルタグ","v1.2.3 のような意味のあるバージョンタグや sha256 ダイジェスト参照。特定のイメージを確実に指す。"]],"think":"latest は『最新号』と書いてある雑誌の棚。来週に同じ棚を見ると別の雑誌が置いてある。バックナンバー（v1.2.3）を指定すれば必ず同じものが取れる。","vs":"latest は開発の手元では便利だが、本番デプロイには v1.2.3 や sha256 ダイジェストで固定する。latest が最新バージョンを自動で指すという保証はない（作成者が更新しなければ古いままになる）。","opt":["正解。latest は可変で再現性がない。","プライベートレジストリでも latest は使える。","latest の更新は自動ではなく作成者が push した内容次第。","圧縮率とタグ名は無関係。"]}'),

  ('dca-q40', 'Image Creation, Management, and Registry',
   'Docker イメージのレイヤーについて正しい説明はどれか。',
   NULL,
   '["各レイヤーは読み取り専用で、コンテナ実行時に書き込み可能なレイヤーが最上位に追加される","各レイヤーは書き込み可能で、コンテナが変更するたびに新しいレイヤーが追加される","レイヤーはイメージ間で共有されないため、同じベースイメージでも毎回ダウンロードが必要","RUN 命令1つにつき必ず1レイヤーが作られ、AND（&&）でつないでも複数レイヤーになる"]',
   0, '[0]', 'single',
   '{"asked":"イメージレイヤーの読み取り専用性と CoW（Copy-on-Write）の仕組みを理解しているか。","terms":[["読み取り専用レイヤー","Dockerfile の各命令（FROM・RUN・COPY など）が1レイヤーを作る。コンテナ実行後も変更不可。複数イメージで同じレイヤーを共有できる（ディスク効率）。"],["書き込み可能レイヤー（コンテナレイヤー）","コンテナ起動時に最上位に追加される薄い書き込み層。コンテナ削除で消える。"],["CoW（Copy-on-Write）","下のレイヤーのファイルを変更するとき、そのファイルをコンテナレイヤーにコピーしてから変更する仕組み。元のレイヤーは変化しない。"]],"think":"透明なフィルム（レイヤー）を重ねた OHP シート。下のシートは変更できないが、一番上に白紙のシート（コンテナレイヤー）を置いて書き込める。複数のシート束（イメージ）で共通の下層フィルムを使い回せる。","vs":"RUN 命令を && でつなぐと1つの RUN で1レイヤーになる（複数行でも1命令＝1レイヤー）。これがイメージサイズ削減の基本テクニック。","opt":["正解。イメージレイヤーは読み取り専用、実行時に書き込み層が追加。","イメージレイヤーは不変（読み取り専用）。","同じレイヤーはホスト上で共有・再利用される。","&&でつないだRUNは1命令=1レイヤー。"]}'),

  ('dca-q41', 'Image Creation, Management, and Registry',
   'docker image prune と docker system prune の違いとして正しいものはどれか。',
   NULL,
   '["image prune は未使用イメージのみ削除、system prune はイメージ・コンテナ・ネットワーク・ビルドキャッシュを一括削除する","system prune はボリュームも必ず削除するが image prune は削除しない","image prune は全イメージを削除し system prune は選択削除する","どちらも実行中のコンテナが使うイメージも削除する"]',
   0, '[0]', 'single',
   '{"asked":"各 prune コマンドのスコープを正確に理解しているか。","terms":[["docker image prune","dangling（タグなし・参照なし）イメージを削除。-a フラグで未使用の全イメージを対象にできる。"],["docker system prune","停止中コンテナ・未使用ネットワーク・dangling イメージ・ビルドキャッシュを一括削除。-v フラグを付けるとボリュームも削除（デフォルトは除外）。"]],"think":"image prune は『使っていない服だけ処分』。system prune は『クローゼット・本棚・倉庫をまとめて大掃除』。でもボリューム（貴重品）はデフォルトでは含まれない。","vs":"system prune はデフォルトではボリュームを削除しない（-v を付けないと安全）。実行中コンテナが使うイメージは両方とも削除されない。","opt":["正解。image prune は未使用イメージのみ、system prune は広範囲を一括削除。","system prune のデフォルトはボリュームを除外。-v が必要。","image prune は全削除ではなく未使用のみ。","実行中コンテナが使うリソースはどちらも削除しない。"]}'),

  ('dca-q42', 'Image Creation, Management, and Registry',
   'マルチプラットフォームイメージ（linux/amd64 と linux/arm64 の両方）をビルドして push するコマンドはどれか。',
   NULL,
   '["docker buildx build --platform linux/amd64,linux/arm64 --push -t myimage:latest .","docker build --platform linux/amd64,linux/arm64 -t myimage:latest . && docker push","docker build --multi-arch -t myimage:latest .","docker manifest create でイメージを手動で結合してから push する"]',
   0, '[0]', 'single',
   '{"asked":"マルチプラットフォームビルドに buildx が必要であることと、その基本的な使い方を知っているか。","terms":[["docker buildx","QEMU や BuildKit を使って複数アーキテクチャ向けイメージを1コマンドでビルドできる Docker の拡張ビルドツール。"],["--platform","ビルド対象のプラットフォームをカンマ区切りで指定する。マルチプラットフォームは --push と同時に使うのが一般的（ローカルにはマルチアーキの全キャッシュを保持できないため）。"]],"think":"複数言語版の書籍（マルチアーキイメージ）を同時に出版するには、特殊な印刷設備（buildx）が必要。通常の docker build（普通のプリンター）では1言語版しか作れない。","vs":"docker build（buildx なし）では --platform で複数指定してもマルチプラットフォームビルドはできない。docker manifest は手動で manifest list を作る方法で、buildx の方が現代的。","opt":["正解。buildx + --platform + --push が基本構文。","通常の docker build では複数プラットフォームビルドは不可。","--multi-arch というフラグは存在しない。","manifest create は古い手動の方法。buildx の方が推奨。"]}'),

  ('dca-q43', 'Image Creation, Management, and Registry',
   'FROM scratch を使う Dockerfile の主な用途はどれか。',
   'FROM scratch\nCOPY myapp /myapp\nCMD ["/myapp"]',
   '["シェルや OS ライブラリを含まない完全に最小限のイメージを作るとき（静的バイナリの配布など）","scratch は Docker の最新公式 Ubuntu イメージのエイリアス","scratch はセキュリティテスト用の隔離環境を作るための特殊ベースイメージ","scratch ベースのイメージは HEALTHCHECK が使えない"]',
   0, '[0]', 'single',
   '{"asked":"FROM scratch の意味と適切なユースケースを理解しているか。","terms":[["FROM scratch","何もないゼロの状態からイメージを構築する。/bin/sh も libc もない。静的にリンクされたバイナリ（Go や Rust で作った実行ファイル等）を単体で配置するだけでコンテナが動く。"],["静的バイナリ","実行に必要なライブラリをすべて内包したバイナリ。OS のライブラリに依存しないため scratch ベースで動く。"]],"think":"何もない更地（scratch）に、自給自足できる移動式ハウス（静的バイナリ）だけ置く。電気・水道（OS ライブラリ）なしで完結するから更地でも動く。","vs":"scratch は Ubuntu の別名ではない。Alpine はシェル・libc を含む超軽量ベースイメージで scratch より実用的な場面が多い。HEALTHCHECK は scratch ベースでも使える（curl などがないと CMD で使うコマンドに制限があるだけ）。","opt":["正解。OS ライブラリ不要の静的バイナリを配布するための最小イメージ構築。","scratch は Ubuntu ではない。空のベースを意味する。","セキュリティテスト専用ではない。","HEALTHCHECK 自体は使える（ツールがないと制限されるが命令の使用は可能）。"]}'),

  ('dca-q44', 'Image Creation, Management, and Registry',
   'Dockerfile の USER 命令の主な目的はどれか。',
   'FROM ubuntu\nRUN useradd -m appuser\nUSER appuser\nCMD ["myapp"]',
   '["コンテナのプロセスを root 以外のユーザーで実行してセキュリティを高める","ホストマシンへのログイン権限を持つユーザーを作成する","コンテナ内のファイルの所有者を一括変更する","USER 命令がないとコンテナはまったく起動しない"]',
   0, '[0]', 'single',
   '{"asked":"USER 命令のセキュリティ上の意義を理解しているか。","terms":[["USER","それ以降の RUN・CMD・ENTRYPOINT を指定ユーザーで実行する命令。コンテナ内の root 権限を制限する基本的なセキュリティ対策。"],["コンテナの root","デフォルトでは root で実行される。コンテナからホストへの脱出（コンテナエスケープ）リスクを高める。"]],"think":"工場の作業員に『工場長（root）権限』を与えると、機械全部を勝手に操作できる。一般作業員（appuser）の権限に絞れば、担当ライン以外は触れない。最小権限の原則。","vs":"USER はホストログインとは無関係（コンテナ内の権限のみ）。ファイル所有者変更は chown。USER なしでも起動はする（ただし root 実行になる）。","opt":["正解。非 root 実行でセキュリティリスクを低減する。","ホストログインとは無関係。","ファイル所有者一括変更は chown コマンドや COPY --chown で行う。","USER なしでも起動する（root で実行されるだけ）。"]}'),

  ('dca-q45', 'Image Creation, Management, and Registry',
   'docker image inspect で確認できる情報として正しくないものはどれか。',
   NULL,
   '["そのイメージを使って実行しているコンテナの一覧","イメージのレイヤー（RootFS.Layers）","設定された環境変数（Config.Env）","ENTRYPOINT と CMD の設定"]',
   0, '[0]', 'single',
   '{"asked":"docker image inspect で確認できる情報の範囲を正確に把握しているか。","terms":[["docker image inspect","イメージのメタデータ（レイヤーハッシュ・OS・アーキテクチャ・ENV・CMD・ENTRYPOINT など）を JSON 形式で表示する。"],["docker ps","実行中のコンテナを一覧表示する。イメージに関連するコンテナはここで確認する。"]],"think":"車の車検証（image inspect）には車の仕様（エンジン・排気量・色）は書いてある。でもその車が今どこを走っているか（実行中コンテナ）は GPS（docker ps）で確認する。","vs":"どのコンテナがそのイメージを使っているかは docker ps --filter ancestor=<image> で確認する。image inspect はイメージ自体のメタデータのみ。","opt":["正解（これが確認できない情報）。コンテナ一覧は docker ps で確認する。","レイヤー情報は確認できる。","環境変数は確認できる。","ENTRYPOINT と CMD は確認できる。"]}'),

  ('dca-q46', 'Image Creation, Management, and Registry',
   'BuildKit（DOCKER_BUILDKIT=1）を有効にした場合のメリットとして正しくないものはどれか。',
   NULL,
   '["Dockerfile に記述した全ステージを必ず順番通りにビルドするため並列ビルドができない","ビルドキャッシュの効率が向上する","シークレットをビルド時にファイルシステムに残さず安全に使える（--secret）","未使用のビルドステージをスキップして高速化できる"]',
   0, '[0]', 'single',
   '{"asked":"BuildKit が従来のビルダーより優れている点を理解しているか。また並列ビルドに関する誤解を排除できるか。","terms":[["BuildKit","Docker 18.09 以降のデフォルトビルドエンジン。並列ビルド・キャッシュ改善・--secret サポート・未使用ステージスキップなどを提供する。"],["--secret（BuildKit）","ビルド時のみ使用するシークレット（SSH キー・トークン）をイメージレイヤーに残さず使える機能。"]],"think":"BuildKit は工場の生産ラインを最適化して、独立した工程を並列化し、使わない工程はスキップして効率化する。並列化できないのは古い従来ビルダーの方。","vs":"BuildKit の利点は並列ビルドを可能にすること。選択肢 A の『並列ビルドができない』は正反対（これが誤りの選択肢）。","opt":["正解（これが誤り）。BuildKit は並列ビルドをサポートする。","キャッシュ改善は正しい利点。","--secret は BuildKit の重要なセキュリティ機能。","未使用ステージのスキップも BuildKit の機能。"]}'),

  -- ============================================================
  -- Installation and Configuration (q47–q54)
  -- ============================================================

  ('dca-q47', 'Installation and Configuration',
   'コンテナと仮想マシン（VM）の最も根本的な違いはどれか。',
   NULL,
   '["コンテナはホスト OS のカーネルを共有するが、VM は独自のカーネルを持つハイパーバイザー上で動く","コンテナは VM よりも強力なセキュリティ分離を提供する","VM はコンテナより起動が速い","コンテナは CPU 仮想化を使うが VM は OS 仮想化を使う"]',
   0, '[0]', 'single',
   '{"asked":"コンテナと VM の根本的なアーキテクチャの違い（カーネル共有 vs ハイパーバイザー）を理解しているか。","terms":[["コンテナ","ホスト OS のカーネルを共有しながら、名前空間（namespace）と cgroups で隔離されたプロセス群。軽量・高速起動。"],["仮想マシン（VM）","ハイパーバイザー（VMware・KVM 等）の上で独自の OS カーネルごと動く。完全な隔離だが起動が遅くリソース消費が大きい。"]],"think":"VM はアパートの各部屋（独自の壁・床・天井）。コンテナは同じ建物の中に仕切りをつけた共有オフィス。建物の基礎（カーネル）は共有。仕切り（名前空間）で独立しているように見える。","vs":"セキュリティ分離は VM の方が強い（カーネル共有の脆弱性がない）。起動速度はコンテナが速い（OS 起動が不要）。","opt":["正解。カーネル共有（コンテナ）vs ハイパーバイザー（VM）が根本的な違い。","セキュリティ分離は一般的に VM の方が強い。","VM の起動は OS ブートを含むため遅い。","逆。コンテナは OS 仮想化（名前空間）、VM は CPU/ハードウェア仮想化。"]}'),

  ('dca-q48', 'Installation and Configuration',
   'Docker が利用する Linux カーネルの2つの主要な機能はどれか。',
   NULL,
   '["名前空間（Namespaces）と cgroups（Control Groups）","iptables と OverlayFS","systemd と seccomp","AppArmor と VXLAN"]',
   0, '[0]', 'single',
   '{"asked":"Docker がコンテナの隔離とリソース制限に使う Linux カーネル機能2つを答えられるか。","terms":[["名前空間（Namespaces）","プロセス・ネットワーク・ファイルシステム・ユーザーなどの『見え方』を分離する機能。各コンテナは独自の名前空間内に閉じ込められる。"],["cgroups（Control Groups）","CPU・メモリ・ディスク I/O などのリソース使用量を制限・計測する機能。コンテナが使えるリソース上限を設定する。"]],"think":"名前空間は『コンテナに独自の部屋番号（PID・IP アドレス・ファイルパス）を与える』仕組み。cgroups は『各部屋が使えるガス・水道・電気（CPU・メモリ）の上限を決める』メーター。","vs":"iptables はネットワークフィルタリング（Docker のネットワーク実装で使う）。OverlayFS はストレージドライバー。どちらも重要だが隔離とリソース制限の主役は Namespaces と cgroups。","opt":["正解。Docker の2大基盤技術は Namespaces と cgroups。","iptables と OverlayFS は重要だが隔離の主役ではない。","systemd と seccomp は隔離の主役ではない。","AppArmor と VXLAN も違う。"]}'),

  ('dca-q49', 'Installation and Configuration',
   'コンテナのメモリ使用量を 512MB に制限するコマンドはどれか。',
   NULL,
   '["docker run --memory 512m myimage","docker run --mem-limit 512mb myimage","docker run --max-memory=512 myimage","docker run --cgroup-memory 512m myimage"]',
   0, '[0]', 'single',
   '{"asked":"cgroups を使ったメモリ制限の正しいフラグを知っているか。","terms":[["--memory（または -m）","コンテナが使えるメモリの上限を設定する。単位は b/k/m/g。コンテナが上限を超えるとプロセスが OOM Kill される。"],["--memory-swap","メモリ + スワップの合計上限。--memory と同じ値にするとスワップ無効化。"]],"think":"テナント（コンテナ）が使える電気（メモリ）の契約アンペア（上限）を設定する。上限を超えると自動でブレーカー（OOM Kill）が落ちる。","vs":"--mem-limit や --cgroup-memory というフラグは存在しない。単位は 512mb でなく 512m（大文字 M か小文字 m、b は bytes を意味する）。正確には 512m または 536870912（bytes）。","opt":["正解。--memory 512m が正しいフラグと値の形式。","--mem-limit は存在しないフラグ。","--max-memory は存在しないフラグ。","--cgroup-memory は存在しないフラグ。"]}'),

  ('dca-q50', 'Installation and Configuration',
   '/etc/docker/daemon.json の役割はどれか。',
   '{\n  "log-driver": "json-file",\n  "log-opts": {\n    "max-size": "10m",\n    "max-file": "3"\n  },\n  "insecure-registries": []\n}',
   '["Docker デーモン（dockerd）の設定ファイルで、ログドライバーやレジストリ設定などを永続的に設定する","docker run のデフォルト引数を設定するファイル","Dockerfile のデフォルト設定を上書きするファイル","Docker Compose のデフォルト設定ファイル"]',
   0, '[0]', 'single',
   '{"asked":"daemon.json が Docker デーモン全体の設定ファイルであることを理解しているか。","terms":[["daemon.json","Docker デーモン（dockerd）の設定を JSON で記述する。変更後は systemctl reload docker または再起動が必要。Linux では /etc/docker/daemon.json、Windows は別パス。"],["設定例","log-driver（デフォルトログドライバー）・insecure-registries（HTTP レジストリ許可）・default-ulimits・dns・registry-mirrors など。"]],"think":"本社（Docker デーモン）の社内規定書（daemon.json）。ここに書いたルールが全コンテナ（社員）に適用される。個別コンテナの設定（docker run の引数）は上書き可能。","vs":"docker run の引数は個別コンテナへの指示で daemon.json とは別。Dockerfile はイメージのビルド手順。Compose は複数コンテナのオーケストレーション定義。","opt":["正解。Docker デーモン全体に適用される設定ファイル。","docker run のデフォルト引数ではない（個別起動時の指定）。","Dockerfile の上書きではない。","Compose 設定ではない。"]}'),

  ('dca-q51', 'Installation and Configuration',
   'Docker の json-file ログドライバーで max-size と max-file を設定する主な目的はどれか。',
   NULL,
   '["ログファイルがホストのディスクを無制限に消費しないよう、ローテーションと上限を設定する","コンテナのメモリ使用量を制限する","ログをリモートサーバーに転送する","ログのフォーマット（JSON vs テキスト）を変更する"]',
   0, '[0]', 'single',
   '{"asked":"json-file ログドライバーのローテーション設定の必要性を理解しているか。","terms":[["json-file ログドライバー","デフォルトのログドライバー。ログを /var/lib/docker/containers/<id>/<id>-json.log に保存する。","デフォルトでは max-size の設定がなくディスクが枯渇する可能性がある。"],["max-size / max-file","max-size でログファイル1つの上限サイズ（例: 10m）、max-file でファイルの最大数を指定する。ローテーションでディスク消費を抑制する。"]],"think":"日記（ログ）を毎日書いていたらノートが無限に増える。max-size=10m で1冊のノートの最大ページ数を決め、max-file=3 で最大3冊まで保管。古いノートは自動廃棄。","vs":"メモリ制限は --memory フラグ。リモート転送は syslog や fluentd ドライバー。フォーマット変更はログドライバー自体の変更。","opt":["正解。ディスク消費防止のためのログローテーション設定。","メモリ制限は --memory フラグ。","リモート転送は別のログドライバー（syslog 等）。","json-file ドライバーのフォーマットは JSON 固定。"]}'),

  ('dca-q52', 'Installation and Configuration',
   'docker context の役割はどれか。',
   NULL,
   '["接続先の Docker デーモン（ローカル・リモート・Swarm 等）を切り替える設定を管理する","コンテナのネットワーク名前空間（context）を設定する","Dockerfile のビルドコンテキストを事前に定義する","docker compose のプロジェクト名を設定する"]',
   0, '[0]', 'single',
   '{"asked":"docker context の目的（デーモン接続先の切り替え）を理解しているか。","terms":[["docker context","Docker CLI が接続するエンドポイント（Unix ソケット・TCP・SSH 等）を名前付きで管理する仕組み。docker context use <name> で切り替える。"],["用途","ローカルの Docker Desktop から SSH 経由でリモートサーバーの Docker デーモンに接続したり、複数の Swarm クラスタを切り替える際に便利。"]],"think":"テレビのリモコン（docker CLI）で、どのテレビ（Docker デーモン）を操作するか切り替えるチャンネル設定。context を変えることで、同じ docker コマンドが別のサーバーのデーモンに届く。","vs":"ビルドコンテキスト（docker build の . で渡すディレクトリ）とは全く別の概念。名前が似ているので混同注意。","opt":["正解。接続先デーモンを切り替える設定の管理。","ネットワーク名前空間の設定ではない。","ビルドコンテキストの事前定義ではない（別の概念）。","Compose のプロジェクト名は COMPOSE_PROJECT_NAME 環境変数。"]}'),

  ('dca-q53', 'Installation and Configuration',
   'docker system df の出力から確認できる情報はどれか。',
   NULL,
   '["イメージ・コンテナ・ボリューム・ビルドキャッシュが使用しているディスク容量","CPU と メモリの使用率","ネットワーク帯域幅の使用量","実行中コンテナのプロセス一覧"]',
   0, '[0]', 'single',
   '{"asked":"docker system df コマンドの出力内容を知っているか。","terms":[["docker system df","Docker が使用しているディスクスペースをリソース種別（Images・Containers・Volumes・Build Cache）ごとに表示する。df = disk free の略。"],["RECLAIMABLE","削除しても構わない（未使用）リソースが占めるサイズ。prune コマンドで回収できる。"]],"think":"家全体の荷物の量（ディスク使用量）を部屋ごと（イメージ・コンテナ・ボリューム）に集計したリスト。どの部屋が散らかっているか一目でわかる。","vs":"CPU/メモリは docker stats（リアルタイム）。ネットワーク帯域は stats で確認。プロセス一覧は docker top。","opt":["正解。ディスク使用量をリソース種別ごとに表示。","CPU/メモリは docker stats で確認する。","ネットワーク帯域も docker stats。","プロセス一覧は docker top。"]}'),

  ('dca-q54', 'Installation and Configuration',
   'コンテナの CPU 使用を 1.5 コア相当に制限するコマンドはどれか。',
   NULL,
   '["docker run --cpus 1.5 myimage","docker run --cpu-count 1.5 myimage","docker run --cpu-limit=150% myimage","docker run --cgroup-cpus 1.5 myimage"]',
   0, '[0]', 'single',
   '{"asked":"CPU リソース制限の正しいフラグ（--cpus）を知っているか。","terms":[["--cpus","コンテナが使用できる CPU 数の上限を小数で指定する。1.5 は 1.5 コア相当の CPU 時間を使用できる。cgroups の cpu.cfs_quota_us で実装される。"],["--cpu-shares","CPU 利用の相対的な優先度ウェイトを設定する（デフォルト 1024）。上限ではなく優先度。"]],"think":"コンテナに『この工場では最大 1.5 台のロボット分の作業量（CPU）まで』と上限を設ける。--cpus は絶対上限、--cpu-shares は混雑時の優先度（空きがあれば多く使える）。","vs":"--cpu-count や --cpu-limit、--cgroup-cpus は存在しないフラグ。--cpus が正しい。パーセント指定（150%）は使えない。","opt":["正解。--cpus 1.5 で 1.5 コア相当の上限を設定。","--cpu-count は存在しないフラグ。","パーセント指定と --cpu-limit は存在しないフラグ。","--cgroup-cpus は存在しないフラグ。"]}'),

  -- ============================================================
  -- Networking (q55–q63)
  -- ============================================================

  ('dca-q55', 'Networking',
   'Docker のデフォルトのブリッジネットワーク（docker0）の特徴として正しいものはどれか。',
   NULL,
   '["コンテナ名での DNS 解決はできず、コンテナ間の通信には IP アドレスを使う必要がある","コンテナ名で相互に名前解決でき、カスタムブリッジと同じ機能を持つ","デフォルトブリッジはコンテナのインターネットアクセスをブロックする","コンテナを起動すると自動で別々のブリッジネットワークに接続される"]',
   0, '[0]', 'single',
   '{"asked":"デフォルトブリッジとカスタムブリッジの機能差（DNS 解決の有無）を理解しているか。","terms":[["デフォルトブリッジ（docker0）","docker run でネットワーク指定なしで起動したとき接続される。コンテナ名での DNS 解決が無効（IP アドレスかリンク機能で通信）。"],["カスタムブリッジ","docker network create で作成したブリッジネットワーク。コンテナ名で自動 DNS 解決が可能。コンテナの分離・管理に推奨。"]],"think":"デフォルトブリッジは古い社宅（名前で呼べず部屋番号で呼ぶ必要がある）。カスタムブリッジは新しいビル（内線番号＝コンテナ名で呼べる）。","vs":"カスタムブリッジを使えば名前解決できる。デフォルトブリッジでもインターネットアクセスは可能（NAT 経由）。コンテナは起動時に1つのネットワークに接続され、複数は docker network connect で追加。","opt":["正解。デフォルトブリッジではコンテナ名 DNS 解決が効かない。","カスタムブリッジの機能でデフォルトブリッジにはない。","デフォルトブリッジもインターネットに NAT でアクセスできる。","自動で別々のネットワークに接続されるわけではない。"]}'),

  ('dca-q56', 'Networking',
   'docker run --network host でコンテナを起動するとどうなるか。',
   NULL,
   '["コンテナはホストのネットワーク名前空間を共有し、ポートマッピングなしでホストのポートを直接使う","コンテナのすべてのポートがホストに自動でマッピングされる","コンテナはネットワークを持たず完全に隔離される","コンテナはホストの eth0 インターフェースを専有して他のコンテナはネットワークを使えなくなる"]',
   0, '[0]', 'single',
   '{"asked":"host ネットワークモードの動作を正確に理解しているか。","terms":[["host ネットワーク","コンテナがホストの network namespace を共有する。コンテナが port 80 をバインドするとホストの port 80 が使われる。-p オプションは不要（かつ無意味）。"],["使用場面","高スループットが必要なアプリ・ネットワーク測定ツールなど。ただしネットワーク分離が失われる。Linux のみのサポート（Mac/Windows の Docker Desktop は効果なし）。"]],"think":"コンテナが仮の住所（コンテナ IP）を使わず、ホストの本住所（ホスト IP・ポート）をそのまま名乗る状態。賃貸（独自 IP）でなく実家（ホストと同じアドレス）に住む。","vs":"完全にネットワーク隔離するのは --network none。自動マッピングは --network host の動作ではなく -P フラグ（ランダムポート割り当て）の機能。","opt":["正解。ホストの network namespace を共有。-p 不要。","自動全マッピングは -P フラグ。host ネットワークとは別。","完全隔離は --network none。","ネットワークを専有するわけではなく、共有するだけ。"]}'),

  ('dca-q57', 'Networking',
   'docker run --network none で起動したコンテナの特徴はどれか。',
   NULL,
   '["ネットワークインターフェースを持たず、外部・他コンテナとの通信が一切できない","ホストのネットワークを共有する","コンテナ間は通信できるが外部ネットワークにはアクセスできない","名前解決のみ無効になる"]',
   0, '[0]', 'single',
   '{"asked":"none ネットワークモードの完全な隔離を理解しているか。","terms":[["none ネットワーク","ループバック（lo）のみで、外部向けのネットワークインターフェースが存在しない完全ネットワーク隔離。"],["用途","オフライン処理（ファイル変換・暗号化処理等）・セキュリティが重要な処理・ネットワーク不要なバッチ処理。"]],"think":"インターネットもイントラネットも繋がっていない完全オフラインのコンピュータ（エアギャップ）。外界と切り離された安全な箱。","vs":"host はホストとネットワーク共有（逆のアプローチ）。none は通信を完全に遮断する。ループバック（127.0.0.1）自体は使えるので、プロセス内の通信（同一コンテナ内のポート通信）は可能。","opt":["正解。外部とのすべての通信が遮断される。","host ネットワークの説明。","none では他コンテナとも通信できない。","名前解決だけでなくネットワーク全体が無効。"]}'),

  ('dca-q58', 'Networking',
   '同じカスタムブリッジネットワークに接続された2つのコンテナが、コンテナ名で相互に通信できる理由はどれか。',
   NULL,
   '["Docker の組み込み DNS サーバーがコンテナ名と IP アドレスの解決を自動で行うため","/etc/hosts ファイルに相手のコンテナ名と IP が自動記述されるため","コンテナが起動する順番に IP が割り当てられるため","iptables のルールでコンテナ名をエイリアスとして設定するため"]',
   0, '[0]', 'single',
   '{"asked":"カスタムブリッジネットワーク上の自動 DNS 解決の仕組みを理解しているか。","terms":[["Docker 組み込み DNS サーバー","127.0.0.11 で動く DNS サーバー。カスタムブリッジ上のコンテナはここに DNS クエリを送り、コンテナ名や NetworkAlias から IP を解決できる。"],["NetworkAlias（--network-alias）","コンテナに追加の DNS 名を付けられる機能。同名エイリアスのコンテナが複数いると DNS ラウンドロビンができる。"]],"think":"社内の内線電話帳（Docker DNS）が『山田さん（コンテナ名）は内線 192.168.1.5 です』と自動で登録してくれる。電話帳（DNS）を引くだけで名前から番号（IP）がわかる。","vs":"/etc/hosts への自動記述はデフォルトブリッジの --link 機能（非推奨）の動作。カスタムブリッジでは DNS サーバーが解決する。IP の割り当て順序は名前解決とは無関係。","opt":["正解。カスタムブリッジには組み込み DNS サーバーが働く。","/etc/hosts の自動記述は古い --link 機能の動作。","IP 割り当て順序は名前解決とは別。","iptables は名前解決ではなく通信経路の制御。"]}'),

  ('dca-q59', 'Networking',
   'コンテナのポートをホストに公開するとき、-p 8080:80 と -P の違いはどれか。',
   NULL,
   '["-p 8080:80 はホスト:コンテナのポートを明示指定、-P は Dockerfile の EXPOSE で公開されたポートをランダムなホストポートに自動マッピング","どちらも同じ動作で書き方が違うだけ","-P は全ポートをホストと同じポート番号でマッピング","-p は UDP のみ、-P は TCP のみサポート"]',
   0, '[0]', 'single',
   '{"asked":"-p（明示指定）と -P（自動マッピング）のポート公開の違いを理解しているか。","terms":[["-p hostPort:containerPort","特定のホストポートとコンテナポートをマッピングする。明示的で制御しやすい。"],  ["-P（大文字）","Dockerfile の EXPOSE で指定されたポートを、ホストのエフェメラルポート（32768〜65535）にランダムにマッピングする。ポート番号は docker port コマンドで確認。"]],"think":"-p は『会議室（ポート）を 8080 番と指定して予約』、-P は『空いている会議室をランダムに割り当ててもらう』。-P は複数コンテナを起動するときの競合を避けられる。","vs":"EXPOSE だけではホストにポートを公開しない（コンテナ間の通信でのみ使われる。-P と組み合わせて初めてホストに公開される）。","opt":["正解。-p は明示指定、-P は EXPOSE のランダム自動マッピング。","動作は異なる。","-P はランダムポートで同一番号ではない。","プロトコルの違いはない。どちらも TCP/UDP 指定可能。"]}'),

  ('dca-q60', 'Networking',
   'Docker の Overlay ネットワークを使う主な場面はどれか。',
   NULL,
   '["Docker Swarm など複数のホストにまたがるコンテナ間の通信","単一ホスト上の複数コンテナ間の通信","コンテナとホストが同じ IP 範囲を共有したいとき","コンテナをネットワークから完全に分離したいとき"]',
   0, '[0]', 'single',
   '{"asked":"Overlay ネットワークの用途（マルチホスト通信）を理解しているか。","terms":[["Overlay ネットワーク","複数の Docker ホストにまたがって仮想的なネットワークを構成する。VXLAN（UDP 4789）を使ってホスト間トンネルを張る。Swarm のサービス間通信に使われる。"],["VXLAN","Layer 2 フレームを UDP でカプセル化してトンネリングする技術。物理的に離れたホストのコンテナを同一 L2 ネットワーク上にいるように見せる。"]],"think":"複数の工場（ホスト）にある機械（コンテナ）を、仮想の社内 LAN（Overlay ネットワーク）でつなぐイメージ。物理的に離れていても同じネットワーク上にいるように見える。","vs":"単一ホスト内はブリッジネットワーク。ホストと IP 共有は Macvlan。完全隔離は none ネットワーク。","opt":["正解。Overlay はマルチホストのコンテナ間通信に使う。","単一ホスト内はブリッジ。","ホストとの IP 共有は Macvlan。","完全隔離は none ネットワーク。"]}'),

  ('dca-q61', 'Networking',
   'Macvlan ネットワークドライバーの主な特徴はどれか。',
   NULL,
   '["コンテナにホストのネットワークインターフェースから直接 MAC アドレスと IP アドレスを割り当て、物理ネットワークに直接接続する","コンテナ間のトラフィックを暗号化して転送する","複数ホスト上のコンテナを一つの L2 ネットワークで接続する","コンテナのネットワークを完全に無効化する"]',
   0, '[0]', 'single',
   '{"asked":"Macvlan の動作（物理ネットワークへの直接接続）を理解しているか。","terms":[["Macvlan","各コンテナに独自の MAC アドレスと IP アドレスを割り当て、物理スイッチや VLAN に直接接続するネットワークドライバー。コンテナが物理デバイスと同じ L2 に所属する。"],["用途","既存の物理ネットワークへの統合・特定 IP が必要な移行案件・ネットワーク機器からコンテナに直接アクセスが必要な場面。"]],"think":"コンテナに実際のネットワーク端子（LAN ポート）を直接挿したようなもの。NAT なし・ブリッジなしで物理スイッチのポートとして認識される。","vs":"Overlay はマルチホスト・暗号化可能。Macvlan は単一ホスト内でも使えて物理 L2 に直結。none はネットワーク無効化。","opt":["正解。物理 NIC 経由で L2 ネットワークに直接接続。","暗号化は Overlay（--opt encrypted）の機能。","マルチホスト L2 は Overlay。","ネットワーク無効化は none。"]}'),

  ('dca-q62', 'Networking',
   'Docker Swarm の ingress ネットワークの役割はどれか。',
   NULL,
   '["Swarm のどのノードに来たリクエストも、サービスの実行コンテナにルーティングするロードバランシングを提供する","外部からのトラフィックをブロックするファイアウォールとして機能する","サービス間の内部通信専用のネットワーク","管理者がサービスの状態を監視するための管理ネットワーク"]',
   0, '[0]', 'single',
   '{"asked":"Swarm の ingress ネットワーク（routing mesh）の機能を理解しているか。","terms":[["ingress ネットワーク","Swarm が自動作成する特殊な Overlay ネットワーク。公開ポートへのリクエストを受け取り、実際にサービスを実行しているノードへルーティングする（routing mesh）。"],["routing mesh","コンテナが実行されていないノードに来たリクエストも、コンテナが動いているノードに転送する仕組み。どのノードの IP でもサービスにアクセスできる。"]],"think":"ホテルの受付（どのノード）に行っても、目的の部屋（コンテナが動いているノード）に案内してくれるルーティング。フロントは何階にあるか知らなくても、案内係が連れて行く。","vs":"ファイアウォール機能は別（iptables や FW ルール）。サービス間内部通信は overlay ネットワーク（ingress とは別に作成する）。管理通信は Swarm の制御プレーンが使う別のネットワーク。","opt":["正解。routing mesh で全ノードがサービスへのリクエストを受け付け転送できる。","ファイアウォール機能は持たない。","内部通信用の overlay と ingress は別ネットワーク。","管理ネットワークは別途存在する。"]}'),

  ('dca-q63', 'Networking',
   'コンテナからホストに向けて通信する際、Docker が使う NAT の仕組みはどれか。',
   NULL,
   '["iptables の MASQUERADE ルールでコンテナの送信元 IP をホストの IP に変換（SNAT）して外部に送信する","コンテナは常にホスト IP を使って通信するため NAT は不要","Docker は NAT を使わず VXLAN で直接外部に通信する","iptables の DNAT で外部からコンテナへの通信のみを変換する"]',
   0, '[0]', 'single',
   '{"asked":"Docker がコンテナのアウトバウンド通信に NAT（MASQUERADE）を使う仕組みを理解しているか。","terms":[["MASQUERADE（SNAT）","コンテナの内部 IP（172.17.x.x 等）を出口インターフェースのホスト IP に変換してインターネットに送信する。応答が返ってくると逆変換して元のコンテナに届ける。"],["DNAT","ホストのポートへの着信をコンテナの IP:ポートに転送する変換。-p オプションで設定したポートマッピングの実装。"]],"think":"オフィスビル（コンテナ群）の電話（通信）はビルの代表番号（ホスト IP）を使って外部に発信する。外からは中の内線（コンテナ IP）が見えない。これが MASQUERADE。","vs":"ホスト IP を使うのは host ネットワークモード（NAT なし）。Overlay ネットワークは VXLAN を使うが NAT の代替ではない。DNAT は受信方向（ポートマッピング）の話。","opt":["正解。iptables MASQUERADE でコンテナ IP をホスト IP に変換する SNAT。","host ネットワークモードが NAT なし。デフォルトブリッジでは NAT がある。","Overlay は別ネットワークの話。NAT を無効化するものではない。","DNAT は受信側の変換（ポートマッピング）。送信側は SNAT（MASQUERADE）。"]}'),

  -- ============================================================
  -- Security (q64–q70)
  -- ============================================================

  ('dca-q64', 'Security',
   'Linux の名前空間（namespace）がコンテナに提供する分離の種類として誤っているものはどれか。',
   NULL,
   '["ディスク I/O 帯域幅の分離","PID（プロセス ID）の分離","ネットワーク（IP アドレス・ポート）の分離","マウントポイント（ファイルシステム）の分離"]',
   0, '[0]', 'single',
   '{"asked":"Linux 名前空間が担う分離の種類とその限界を正確に理解しているか。","terms":[["Linux 名前空間の種類","PID（プロセス）・NET（ネットワーク）・MNT（ファイルシステム）・UTS（ホスト名）・IPC（プロセス間通信）・USER（UID/GID）・TIME・CGROUP の各名前空間がある。"],["cgroups","CPU・メモリ・ディスク I/O などのリソース使用量の制限と計測。分離ではなく制限。"]],"think":"名前空間は『見え方の分離』（他のプロセスが見えない・他の IP が見えない）。cgroups は『使える量の制限』（ガスを 50% まで）。ディスク I/O 帯域幅は cgroups の管轄で、名前空間ではない。","vs":"PID・NET・MNT はすべて名前空間で分離される。ディスク I/O の帯域幅制限は cgroups（blkio サブシステム）の役割で、名前空間は関係ない。","opt":["正解（誤っているもの）。ディスク I/O 帯域幅は cgroups の役割で名前空間ではない。","PID 名前空間はプロセス ID を分離する。","NET 名前空間でネットワークを分離する。","MNT 名前空間でマウントポイントを分離する。"]}'),

  ('dca-q65', 'Security',
   'コンテナに特定の Linux ケイパビリティを追加・削除するフラグはどれか。',
   'docker run --cap-add NET_ADMIN --cap-drop CHOWN myimage',
   '["--cap-add と --cap-drop で個別のケイパビリティを追加・削除できる","--capability=add / --capability=drop が正しいフラグ","--privilege フラグで個別のケイパビリティを指定できる","ケイパビリティは Dockerfile の CAPABILITY 命令でのみ設定できる"]',
   0, '[0]', 'single',
   '{"asked":"Linux capabilities の追加削除のフラグを知っているか。","terms":[["Linux capabilities","root 権限を細かく分解した権限の単位。例: NET_ADMIN（ネットワーク設定）・SYS_PTRACE（プロセストレース）・CHOWN（ファイル所有者変更）など 40 種類以上。"],["--cap-add / --cap-drop","デフォルト capabilities に対して追加・削除する。--privileged は全 capabilities を付与する最も広い権限（非推奨）。"],["原則","最小ケイパビリティの原則：必要なものだけ --cap-add で追加し、不要なデフォルトは --cap-drop で削除する。"]],"think":"社員の権限（capabilities）は役職ごとのデフォルトから、特定業務のために一部権限（ネットワーク設定権限など）を追加し、不要な権限（ファイル所有者変更など）は取り消す人事設定に似ている。","vs":"--privileged は全 capabilities＋デバイスアクセスを与える特権モード。最小権限の原則に反するため本番では避ける。","opt":["正解。--cap-add と --cap-drop が正しいフラグ。","--capability=add/drop というフラグは存在しない。","--privileged は全権限付与。個別指定はできない。","CAPABILITY 命令は Dockerfile に存在しない。"]}'),

  ('dca-q66', 'Security',
   'コンテナのファイルシステムを読み取り専用にしてセキュリティを強化するフラグはどれか。',
   NULL,
   '["docker run --read-only myimage","docker run --immutable myimage","docker run --no-write myimage","docker run --readonly=true myimage"]',
   0, '[0]', 'single',
   '{"asked":"コンテナのルートファイルシステムを読み取り専用にするフラグを知っているか。","terms":[["--read-only","コンテナのルートファイルシステムを読み取り専用にする。コンテナ内のプロセスがファイルシステムを変更できなくなる。"],["tmpfs と組み合わせ","--read-only でも一時ファイルが必要な場合は --tmpfs /tmp などでメモリ上の書き込み可能領域を追加する。"],["セキュリティ効果","マルウェアがファイルシステムを改ざんできなくなる。不変インフラの実現。"]],"think":"美術館の展示品（コンテナ FS）はガラスケースに入れて触れないようにする（--read-only）。必要な作業スペース（/tmp）は別で用意する（--tmpfs）。","vs":"--immutable・--no-write・--readonly=true は存在しないフラグ。","opt":["正解。--read-only がルート FS を読み取り専用にする。","--immutable は存在しないフラグ。","--no-write は存在しないフラグ。","--readonly=true は存在しないフラグ。正しくは --read-only（ハイフンと値なし）。"]}'),

  ('dca-q67', 'Security',
   'Docker Swarm の secret（docker secret）について正しい説明はどれか。',
   NULL,
   '["シークレットは Swarm のマネージャーが暗号化して管理し、必要なサービスのコンテナのみ /run/secrets/ にマウントされる","シークレットは環境変数として全コンテナに自動で配布される","シークレットは Docker Hub に暗号化されて保存される","コンテナを再起動するとシークレットの内容が消える"]',
   0, '[0]', 'single',
   '{"asked":"Docker Swarm secret の配布メカニズムとセキュリティ特性を理解しているか。","terms":[["docker secret","パスワード・API キー・証明書などの機密値を Swarm が Raft ログに暗号化して管理する仕組み。"],["配布の仕組み","サービスがシークレットを必要とするとき、マネージャーが TLS で暗号化した値をワーカーに送信し、コンテナの /run/secrets/<name> に tmpfs でマウントする（メモリ上で、ディスクに書かれない）。"],["スコープ","そのシークレットが紐付けられたサービスのコンテナにのみアクセス可能。"]],"think":"金庫（Swarm マネージャー）が暗証番号（シークレット）を保管し、必要な担当者（サービスのコンテナ）にだけ一時的に手渡す。紙に書き残さず（ディスクに書かない）口頭で伝える（メモリ）。","vs":"環境変数は docker inspect で平文確認できるため機密値には不向き。シークレットは Docker Hub には保存されない（Swarm のみ）。コンテナが動いている間はシークレットにアクセスできる。","opt":["正解。Swarm が暗号化管理し /run/secrets/ にのみマウント。","環境変数での配布はない（docker secret は Swarm の機能）。","Docker Hub は関係ない。","サービスが稼働中は継続してアクセス可能。"]}'),

  ('dca-q68', 'Security',
   'コンテナの seccomp プロファイルの主な目的はどれか。',
   NULL,
   '["コンテナ内のプロセスが呼び出せるシステムコールを制限し、カーネル攻撃面を減らす","コンテナの CPU 使用率を制限する","コンテナのネットワーク通信を暗号化する","コンテナ間のファイルシステムアクセスを制御する"]',
   0, '[0]', 'single',
   '{"asked":"seccomp（Secure Computing Mode）の役割とカーネル攻撃面の削減を理解しているか。","terms":[["seccomp","Linux カーネルの機能。コンテナ内プロセスが使えるシステムコール（カーネル API）を許可リストまたは拒否リストで制限する。"],["デフォルト seccomp プロファイル","Docker はデフォルトで約 300 のシステムコールのうち危険な 44 を禁止したプロファイルを適用する。--security-opt seccomp=unconfined で無効化できる（非推奨）。"]],"think":"コンテナが使える OS への命令（システムコール）を制限する検閲官。危険な命令（カーネルモジュールのロード・マウントなど）を使おうとすると弾く。攻撃者がコンテナに侵入してもカーネルに触れる手段を制限できる。","vs":"CPU 制限は cgroups。ネットワーク暗号化は TLS や Overlay の暗号化オプション。ファイルシステムアクセス制御は AppArmor や SELinux が担う。","opt":["正解。システムコールの制限でカーネル攻撃面を削減する。","CPU 制限は cgroups の役割。","ネットワーク暗号化は別の機能。","ファイルシステムアクセス制御は AppArmor/SELinux。"]}'),

  ('dca-q69', 'Security',
   '--privileged フラグでコンテナを起動することが危険な主な理由はどれか。',
   NULL,
   '["コンテナがホストのほぼすべてのデバイスにアクセスでき、カーネルへの操作も可能になりコンテナエスケープのリスクが高まる","--privileged はコンテナを root で実行するだけで危険性は低い","--privileged はネットワーク通信の暗号化を無効化する","--privileged はコンテナのファイルシステムをホストと共有する"]',
   0, '[0]', 'single',
   '{"asked":"--privileged の広範な権限付与とコンテナエスケープのリスクを理解しているか。","terms":[["--privileged","ほぼすべての Linux capabilities を付与し、ホストのデバイス（/dev/*）へのアクセスを許可し、AppArmor/seccomp プロファイルを無効化する。","コンテナとホストの境界がほぼなくなる。"],["コンテナエスケープ","コンテナ内から操作してホストシステムに不正アクセスすること。--privileged はこのリスクを大幅に高める。"]],"think":"普通の従業員（コンテナ）に会社全体の管理者パスワード（--privileged）を渡すと、施錠された全部屋（ホストのデバイス・カーネル）に入れてしまう。最小権限の原則の真逆。","vs":"--privileged は単なる root 実行より遥かに広い。root で実行しても capabilities は制限されている。--privileged は capabilities・デバイス・seccomp・AppArmor すべてを解除する。","opt":["正解。広大な権限でコンテナエスケープのリスクが高まる。","root 実行より遥かに危険。","ネットワーク暗号化の無効化ではない。","ホスト FS との共有は --privileged の主な危険性ではない（--volume のほうが直接的）。"]}'),

  ('dca-q70', 'Security',
   'Docker Content Trust（DCT）を有効にする環境変数と、その効果はどれか。',
   NULL,
   '["DOCKER_CONTENT_TRUST=1 で、署名されていないイメージの pull/push を拒否する","DOCKER_TRUST_ALL=1 で、すべてのイメージの署名を検証する","DCT を有効にすると、イメージが自動的に暗号化される","DCT はプライベートレジストリではサポートされない"]',
   0, '[0]', 'single',
   '{"asked":"Docker Content Trust（Notary ベースの署名検証）の有効化方法と効果を理解しているか。","terms":[["DOCKER_CONTENT_TRUST=1","この環境変数を設定すると、docker pull/push 時にイメージの署名を Notary サーバーで検証する。署名されていないイメージは拒否される。"],["Notary","Docker がコンテンツへの署名と検証に使うサーバー。Docker Hub や対応プライベートレジストリで使用可能。"]],"think":"郵便物（イメージ）に差出人の実印（署名）がないと受け取り拒否する宅配ボックス（DCT 有効環境）。実印があれば本物だと確認できる。","vs":"DOCKER_TRUST_ALL は存在しない環境変数。DCT は暗号化ではなく署名検証（内容は暗号化されない）。対応プライベートレジストリであれば DCT は使用可能。","opt":["正解。DOCKER_CONTENT_TRUST=1 で未署名イメージを拒否する。","DOCKER_TRUST_ALL は存在しない環境変数。","DCT は署名検証であり暗号化ではない。","対応レジストリではプライベートでも DCT は使用できる。"]}'),

  -- ============================================================
  -- Storage and Volumes (q71–q81)
  -- ============================================================

  ('dca-q71', 'Storage and Volumes',
   'Docker ボリューム・バインドマウント・tmpfs の違いとして正しいものはどれか。',
   NULL,
   '["ボリュームは Docker が管理するストレージ、バインドマウントはホストのディレクトリを直接マウント、tmpfs はメモリ上の一時ストレージ","バインドマウントは Docker が管理するストレージ、ボリュームはホストのディレクトリを直接マウント","tmpfs はディスク上の永続ストレージでボリュームよりも大容量","3つはすべて同一の機能で書き方だけが異なる"]',
   0, '[0]', 'single',
   '{"asked":"3種類のストレージオプションの管理主体・場所・永続性の違いを理解しているか。","terms":[["Docker ボリューム","Docker が /var/lib/docker/volumes/ で管理する。Docker CLI で作成・削除・バックアップできる。コンテナ間の共有や本番環境に推奨。"],["バインドマウント","ホストの任意のパスをコンテナにマウント。ホスト側のファイルに直接アクセスできる。開発環境でのコードの即時反映に便利。本番では Docker が管理できない（依存度が高い）。"],["tmpfs","コンテナのメモリ上に一時ストレージを作る。コンテナ停止で消える。機密情報の一時保管や高速 I/O に使う。"]],"think":"ボリュームは倉庫（Docker 管理の決まった場所に保管）。バインドマウントは自分の机の引き出し（ホストの好きな場所を直接使う）。tmpfs はメモ帳（使い終わったら消える、メモリ上だけ）。","vs":"本番ではボリュームを推奨（移植性・バックアップ容易）。開発ではバインドマウントが便利（ホストコードを即時反映）。","opt":["正解。3つのストレージタイプの正しい説明。","逆の説明。","tmpfs はメモリ上（非永続）。","3つは全く異なる動作をする。"]}'),

  ('dca-q72', 'Storage and Volumes',
   '名前付きボリュームと匿名ボリュームの違いはどれか。',
   NULL,
   '["名前付きボリュームは docker volume ls で確認・再利用できる。匿名ボリュームはコンテナ削除時に docker rm -v で一緒に削除できる","匿名ボリュームは docker volume create で作成し、名前付きは Dockerfile で作成される","名前付きボリュームはコンテナ削除で自動削除される","匿名ボリュームはコンテナ間で共有できる"]',
   0, '[0]', 'single',
   '{"asked":"名前付きボリュームと匿名ボリュームの管理上の違いと削除動作を理解しているか。","terms":[["名前付きボリューム","docker volume create mydata や -v mydata:/path で作成。名前で識別・再利用が可能。docker rm しても自動削除されない（永続する）。"],["匿名ボリューム","-v /path（名前なし）または Dockerfile の VOLUME 命令で自動生成。ランダムなハッシュ名が付く。docker rm -v でコンテナと一緒に削除できる。"]],"think":"名前付きボリュームは名刺（名前）のある荷物（倉庫から取り出して再利用できる）。匿名ボリュームは宅配便の番号シールだけで届いた荷物（中身はあるが名前がないので管理しにくい）。","vs":"どちらも docker volume ls に表示される。docker rm だけでは名前付き・匿名ともに削除されない（-v が必要、または docker volume prune）。","opt":["正解。名前付きは再利用可能、匿名は -v で削除できる。","作成方法の説明が逆。","名前付きボリュームはコンテナ削除で自動削除されない。","匿名ボリュームはランダム名で複数コンテナから同時参照はできるが、意図的な共有には名前付きが推奨。"]}'),

  ('dca-q73', 'Storage and Volumes',
   'docker volume inspect myvolume で確認できる情報はどれか。',
   NULL,
   '["ボリュームのマウントポイント（ホスト上のパス）・ドライバー・ラベルなどのメタデータ","ボリュームを使用中のコンテナ一覧","ボリューム内のファイル一覧","ボリュームの I/O 統計情報"]',
   0, '[0]', 'single',
   '{"asked":"docker volume inspect で確認できる情報の範囲を理解しているか。","terms":[["docker volume inspect","ボリュームの詳細メタデータを JSON で表示する。主な項目: Mountpoint（ホスト上のパス）・Driver（ボリュームドライバー名）・Labels・Scope・Options。"]],"think":"不動産登記簿（volume inspect）には土地の所在地（Mountpoint）・広さ・権利情報（Labels）は書いてある。でも誰が今住んでいるか（使用コンテナ）は住民票（docker ps）で確認する。","vs":"使用コンテナの確認は docker ps --filter volume=myvolume。ファイル一覧は ls や docker run + cat。I/O 統計は docker stats やシステムツール（iostat 等）。","opt":["正解。マウントポイント・ドライバー・ラベルなどのメタデータを確認できる。","使用コンテナは docker ps --filter volume で確認。","ファイル一覧は volume inspect では確認できない。","I/O 統計は docker stats やシステムツール。"]}'),

  ('dca-q74', 'Storage and Volumes',
   'Docker のデフォルトのストレージドライバー（overlay2）の仕組みとして正しいものはどれか。',
   NULL,
   '["OverlayFS を使って読み取り専用レイヤーを積み重ね、最上位に書き込み可能なコンテナレイヤーを配置する","overlay2 はすべてのデータをメモリに保存する","overlay2 は各レイヤーを完全にコピーしてから変更を加える","overlay2 は ZFS ベースのファイルシステム"]',
   0, '[0]', 'single',
   '{"asked":"overlay2 ストレージドライバーの動作（OverlayFS＋CoW）を理解しているか。","terms":[["OverlayFS","複数のディレクトリ（レイヤー）を一つのビューに重ねる Linux カーネルのファイルシステム。lower（読み取り専用）と upper（書き込み可能）を合成した merged ビューを提供する。"],["overlay2 ドライバー","Docker がコンテナのファイルシステムを実装するために OverlayFS を利用するストレージドライバー。イメージレイヤーが lower、コンテナレイヤーが upper に対応。"]],"think":"OHP（読み取り専用フィルム＝イメージレイヤー）を何枚も重ねた上に、白紙の上用紙（コンテナレイヤー）を置く。下のフィルムは書き換えず、変更は上用紙にだけ書く（CoW）。","vs":"overlay2 はディスク上のファイルシステム（メモリではない）。完全コピーは aufs や devicemapper の一部動作。ZFS は zfs ドライバーが別途存在する。","opt":["正解。OverlayFS で読み取り専用レイヤーを積み重ね、書き込み可能レイヤーを最上位に置く。","メモリではなくディスク上のファイルシステム。","完全コピーは CoW ではなく別の手法。","overlay2 は OverlayFS ベース。ZFS ではない。"]}'),

  ('dca-q75', 'Storage and Volumes',
   'Docker ボリュームのバックアップを取る一般的な方法はどれか。',
   NULL,
   '["一時コンテナでボリュームをマウントし、tar でアーカイブしてホストに書き出す","docker volume backup コマンドを使う","docker save にボリューム名を渡してバックアップする","Swarm のシークレットとしてボリュームの内容を保存する"]',
   0, '[0]', 'single',
   '{"asked":"Docker ボリュームの標準的なバックアップ手順を知っているか。","terms":[["一時コンテナを使ったバックアップ","docker run --rm -v myvolume:/data -v $(pwd):/backup ubuntu tar czf /backup/myvolume.tar.gz -C /data . のようにして、一時コンテナ経由でボリュームの中身を tar で圧縮しホストに書き出す。"]],"think":"倉庫（ボリューム）の荷物を取り出すには、倉庫に入れる一時作業員（一時コンテナ）を雇って、荷物を梱包（tar）して外に出す。専用のエレベーター（docker volume backup）は存在しない。","vs":"docker volume backup というコマンドは存在しない。docker save はイメージの保存。Swarm シークレットはボリュームバックアップの仕組みではない。","opt":["正解。一時コンテナ＋tar を使ったバックアップが標準手順。","docker volume backup コマンドは存在しない。","docker save はイメージ保存用。","シークレットはボリュームバックアップの仕組みではない。"]}'),

  ('dca-q76', 'Storage and Volumes',
   'docker run --tmpfs /tmp オプションの主な用途はどれか。',
   NULL,
   '["/tmp をメモリ上に作成し、コンテナ停止で内容が消えるが高速な一時ストレージとして使う","/tmp をホストのディレクトリに永続マウントする","コンテナのすべてのファイルシステムをメモリ上に置く","tmpfs はセキュリティのためにコンテナのルートを暗号化する"]',
   0, '[0]', 'single',
   '{"asked":"--tmpfs の動作（メモリ上の一時ストレージ）と用途を理解しているか。","terms":[["tmpfs","RAM（メモリ）上に作成される一時ファイルシステム。ディスク I/O がないため高速。コンテナ停止でデータは消える。"],["用途","①高速な一時ファイル置き場②機密情報（シークレット）を --read-only のコンテナで一時的に書き込む場所③キャッシュの一時保管。"]],"think":"ホワイトボード（tmpfs）に書いた内容は会議中（コンテナ動作中）は使えるが、会議終了（コンテナ停止）で消える。ハードディスク（永続ボリューム）には残らない。","vs":"永続マウントはバインドマウントか named volume。コンテナ全体をメモリには置かない。暗号化機能はない。","opt":["正解。メモリ上の高速一時ストレージ。コンテナ停止で消える。","永続ホストマウントはバインドマウント。","コンテナ全体ではなく指定パスのみ。","tmpfs に暗号化機能はない。"]}'),

  ('dca-q77', 'Storage and Volumes',
   '複数のコンテナが同じボリュームに同時に書き込む際に注意すべき点はどれか。',
   NULL,
   '["Docker はファイルレベルのロックを提供しないため、複数コンテナが同時書き込みするとデータ競合が発生しうる","Docker ボリュームは自動で排他制御を行うため複数コンテナでも安全","ボリュームドライバーが常に書き込みを直列化する","複数コンテナから同じボリュームへの書き込みは Docker がエラーにする"]',
   0, '[0]', 'single',
   '{"asked":"複数コンテナが同一ボリュームを共有する場合のデータ競合リスクを理解しているか。","terms":[["データ競合","複数プロセスが同じファイルを同時に読み書きするとき、書き込みの順序によって結果が変わってしまう問題。OSレベルのロック機構が必要。"],["Docker のボリューム共有","--volumes-from や同じボリューム名で複数コンテナがマウントできる。Docker 自体は排他制御を提供しない。アプリレベルまたは DB などのミドルウェアでの制御が必要。"]],"think":"同じ Google ドキュメント（ボリューム）を複数人（コンテナ）が同時に編集すると上書きや消失が起きる可能性がある。ドキュメント側（アプリ）でロック機能を持っていないと困る。","vs":"Docker はファイルシステムの共有を提供するだけで、ファイルロックはアプリケーション責任。データベース（Postgres 等）はロック機構を内部に持つが、単純なファイル共有は危険。","opt":["正解。Docker は排他制御を提供せずデータ競合が起きうる。","自動排他制御は行われない。","ボリュームドライバーは書き込みを直列化しない。","複数マウント自体はエラーにならない（競合はアプリレベルで管理）。"]}'),

  -- ============================================================
  -- Orchestration (q78–q81)
  -- ============================================================

  ('dca-q78', 'Orchestration',
   'Docker Swarm の config（docker config）と secret の違いとして正しいものはどれか。',
   NULL,
   '["config は非機密の設定ファイル（nginx.conf 等）を配布する。secret は機密値を暗号化して配布する","config と secret は完全に同一の機能","config はボリューム経由で配布され、secret はネットワーク経由で配布される","secret は平文で保存されるが config は暗号化されて保存される"]',
   0, '[0]', 'single',
   '{"asked":"docker config と docker secret の目的の違いを理解しているか。","terms":[["docker config","Swarm で設定ファイル（非機密）をサービスに配布する仕組み。/ファイルパス にマウントされる（secret と同様）。暗号化は任意。"],["docker secret","パスワード・証明書などの機密値を暗号化して Swarm マネージャーが管理し、/run/secrets/ にのみマウントする。"]],"think":"config は『社内規定書』（内容を見られても困らない）。secret は『金庫の暗証番号』（暗号化して厳重管理）。どちらもサービスに配布するが、機密性の扱いが異なる。","vs":"config もメモリ上でマウントされるが暗号化のレベルが異なる。ボリューム・ネットワークの違いはなく、どちらも tmpfs ライクなマウントで渡される。","opt":["正解。config は非機密の設定、secret は機密値を暗号化管理。","目的と暗号化レベルが異なる。","配布経路の違いではない。","逆の説明。secret が暗号化される。"]}'),

  ('dca-q79', 'Orchestration',
   'Swarm サービスのコンテナが HEALTHCHECK で unhealthy になったとき、Swarm はどう対応するか。',
   NULL,
   '["そのタスクを停止して新しいタスクを起動する（自動復旧）","unhealthy のコンテナをそのまま維持してアラートだけを出す","そのノードをドレインして別のノードにすべてのタスクを移動する","サービスが自動で削除される"]',
   0, '[0]', 'single',
   '{"asked":"Swarm がヘルスチェック失敗のタスクをどう扱うかを理解しているか。","terms":[["タスクの自動復旧","HEALTHCHECK で unhealthy になったタスクを Swarm が検知すると、そのタスクを停止して新しいタスクをスケジュールし直す。指定したレプリカ数を維持しようとする自己修復機能。"],["restart-condition","タスクの再起動条件（on-failure・any・none）。デフォルト any。"]],"think":"Swarm はタスクの保護者。具合が悪い（unhealthy）子（コンテナ）がいたら新しい健康な子を呼んで（新タスク起動）、元の子は休ませる（停止）。常に指定人数（レプリカ数）が元気でいるよう管理する。","vs":"単体 docker run の --health-* はステータスを変えるだけで Swarm のような自動再スケジュールはない。Swarm だから自動復旧が機能する。ノードドレインは障害ノード全体の話。","opt":["正解。unhealthy タスクを再スケジュールして自動復旧する。","Swarm は自動復旧を行う。アラートのみではない。","ノードドレインはノード単位の操作。タスク単位ではない。","サービスが削除されることはない。"]}'),

  ('dca-q80', 'Orchestration',
   'docker node update --availability drain <NODE> の効果はどれか。',
   NULL,
   '["そのノードで動いているタスクを別のノードに移動し、新しいタスクをスケジュールしなくなる","そのノードを Swarm から強制的に削除する","そのノードのコンテナを全て停止して削除する","マネージャーノードをワーカーノードに降格する"]',
   0, '[0]', 'single',
   '{"asked":"ノードの drain 状態の意味と用途を理解しているか。","terms":[["drain","そのノードを新しいタスクのスケジュール対象から外し、既存のタスクを他のノードに退避させる。メンテナンス前に使う。"],["availability の3状態","active（通常）・pause（新タスク受け付けない、既存は維持）・drain（新タスク受けない＋既存を退避）。"]],"think":"工場のラインを止めてメンテナンスする前に、作業中の製品（タスク）を別のラインに移してからラインを止める（drain）。ラインを壊したり工場から切り離すわけではない。","vs":"ノードの削除は docker node rm（事前に drain が必要）。コンテナの全削除は drain の副作用として他ノードに移動するが削除ではない。降格は docker node demote。","opt":["正解。タスクを他ノードに移動し新タスクを受け付けなくする。","削除は docker node rm。drain は削除ではない。","コンテナは削除でなく別ノードに移動する。","降格は docker node demote。"]}'),

  ('dca-q81', 'Orchestration',
   'Swarm サービスの配置制約（--constraint）と配置優先度（--placement-pref）の違いはどれか。',
   NULL,
   '["constraint は必須条件でマッチしないノードには絶対配置しない。placement-pref は優先度で、できれば均等分散するが絶対ではない","constraint と placement-pref は同一の機能で書き方だけが異なる","placement-pref は CPU 使用率に基づく自動配置最適化","constraint はマネージャーノードのみに適用される"]',
   0, '[0]', 'single',
   '{"asked":"Swarm の placement constraint（必須条件）と placement preferences（優先度）の違いを理解しているか。","terms":[["--constraint（配置制約）","必須条件。条件を満たさないノードにはタスクを配置しない。node.labels.zone==us-east など。マッチするノードがないとサービスが起動できない。"],["--placement-pref（配置優先度）","ベストエフォートの分散優先度。spread 戦略でデータセンターや AZ をまたがった均等分散を試みる。条件を満たさなくてもエラーにはならない。"]],"think":"constraint は採用条件（英語必須）でミスマッチは不採用。placement-pref は配属希望（東京勤務希望）でできれば希望を叶えるが、東京が満杯なら大阪に配属される。","vs":"どちらも docker service create / update で指定。constraint は厳格、preference は柔軟。AZ 分散には spread の preference を使うのが一般的。","opt":["正解。constraint は必須条件、placement-pref はベストエフォートの優先分散。","2つは動作が全く異なる。","placement-pref は CPU 使用率ベースの最適化ではない。","constraint はどのノードにも適用される（マネージャー限定ではない）。"]}')

